// Adresse interne Docker. Modifier uniquement cette constante pour une autre installation.
const apiBaseUrl = 'http://segmentation-api:8000';
const body = $input.first().json.body;
const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
const message = isObject && typeof body.message === 'string' ? body.message.trim() : '';
const sessionId = isObject && typeof body.sessionId === 'string' ? body.sessionId : '';
// Ne pas normaliser l'identifiant : deux valeurs différentes ne doivent pas fusionner.
const validSession = /^[A-Za-z0-9_-]{8,128}$/.test(sessionId);
const validMessage = message.length > 0 && message.length <= 2000;
const valid = validSession && validMessage;
const error = !validSession
  ? "Le champ 'sessionId' est requis : 8 à 128 caractères parmi lettres ASCII, chiffres, tirets et underscores."
  : "Le champ 'message' doit être un texte non vide de 2000 caractères maximum.";
return [{ json: {
  apiBaseUrl, message, sessionId, valid,
  statusCode: 400,
  body: { ok: false, error }
} }];

const sessionId = $('Configuration').first().json.sessionId;
const output = $input.first().json.output;
const answer = typeof output === 'string' ? output.trim() : '';
return [{ json: answer
  ? { statusCode: 200, body: { ok: true, sessionId, answer } }
  : { statusCode: 502, body: { ok: false, sessionId, error: "L'assistant n'a pas produit de réponse exploitable." } }
}];

const sessionId = $('Configuration').first().json.sessionId;
// Ne pas exposer au demandeur les détails internes ou les identifiants du fournisseur.
return [{ json: { statusCode: 502, body: {
  ok: false, sessionId, error: "L'assistant est temporairement indisponible. Vérifiez le modèle et l'API dans n8n."
} } }];
